const REQUIRED_PRESENTATION_FIELDS = [
  "zoneId",
  "label",
  "teaser",
  "firstCopy",
  "repeatCopy",
  "visualKind",
  "badge",
];

function frozenPresentation(nodeId, draft) {
  const binding = LEVEL_ONE.nodeBindings[nodeId];
  if (!binding) throw new Error(`presentation has no level-one node binding: ${nodeId}`);
  const definition = REWARD_DEFINITIONS[binding.rewardRef];
  if (!definition) {
    throw new Error(`presentation references an unknown reward definition: ${binding.rewardRef}`);
  }
  for (const field of REQUIRED_PRESENTATION_FIELDS) {
    if (typeof draft?.[field] !== "string" || !draft[field].trim()) {
      throw new Error(`${nodeId}.${field} must be a non-empty string`);
    }
  }
  const zoneName = LEVEL_ONE_ZONE_NAMES[draft.zoneId];
  if (!zoneName) throw new Error(`${nodeId} has an unknown zoneId: ${draft.zoneId}`);
  return Object.freeze({
    nodeId,
    zoneId: draft.zoneId,
    zoneName,
    rewardRef: binding.rewardRef,
    semanticType: definition.semanticType,
    label: draft.label,
    teaser: draft.teaser,
    firstCopy: draft.firstCopy,
    repeatCopy: draft.repeatCopy,
    visualKind: draft.visualKind,
    badge: draft.badge,
  });
}

const bindingNodeIds = Object.keys(LEVEL_ONE.nodeBindings).sort();
const presentationNodeIds = Object.keys(presentationDrafts).sort();
if (
  bindingNodeIds.length !== presentationNodeIds.length
  || bindingNodeIds.some((nodeId, index) => nodeId !== presentationNodeIds[index])
) {
  throw new Error("level-one presentations must cover every bound node exactly once");
}

export const LEVEL_ONE_NODE_PRESENTATIONS = Object.freeze(Object.fromEntries(
  Object.entries(presentationDrafts).map(([nodeId, draft]) => [
    nodeId,
    frozenPresentation(nodeId, draft),
  ]),
));

export function presentationForLevelOneNode(nodeId, fallback = null) {
  return LEVEL_ONE_NODE_PRESENTATIONS[String(nodeId || "")] || fallback;
}
